import numpy as np
from typing import List

class TrainingAnt:
    def __init__(self, ant_id: int, graph):
        self.ant_id = ant_id
        self.graph = graph
        self.path = []

    def get_path(self) -> List[int]:
        """Zwraca przebytą przez mrówkę ścieżkę (wymagane przez engine.py)."""
        return self.path

    def train_on_sequence(self, target_sequence: List[int], force_path: bool = False) -> float:
        """
        Główna metoda ucząca mrówki.
        force_path=True: Faza Supervised (podąża za wzorcem).
        force_path=False: Faza ACO (wybiera drogę na podstawie feromonów).
        """
        if force_path:
            self.path = list(target_sequence)
            return 1.0
        
        start_token = target_sequence[0]
        self.path = [start_token]
        current_token = start_token
        
        # Generowanie sekwencji krok po kroku
        for _ in range(len(target_sequence) - 1):
            probs = self.graph.get_transition_probabilities(current_token)
            
            # Losowanie następnego tokenu na podstawie wag feromonowych
            if np.sum(probs) > 0:
                next_token = np.random.choice(len(probs), p=probs)
            else:
                next_token = np.random.choice(len(probs))
                
            self.path.append(int(next_token))
            current_token = next_token
            
        return self.calculate_reward(self.path, target_sequence)

    def calculate_reward(self, path: List[int], target: List[int]) -> float:
        """Oblicza nagrodę na podstawie pokrycia się sekwencji."""
        if not path or not target:
            return 0.0
        matches = sum(1 for p, t in zip(path, target) if p == t)
        return matches / len(target)
